import java.util.*;

public class Main {
    static int n, t;
    static char[][] sci, cap;
    static int[][] dis;
    static int[][][][][] dp;
    static final int[] dx = {1, -1, 0, 0};
    static final int[] dy = {0, 0, 1, -1};
    static final int INF = 1000000000;

    static class Edge {
        int to, rev;
        long cap;
        Edge(int to, int rev, long cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        int n, s, t;
        ArrayList<ArrayList<Edge>> g;
        int[] level, it;

        Dinic(int n, int s, int t) {
            this.n = n;
            this.s = s;
            this.t = t;
            g = new ArrayList<>();
            for (int i = 0; i < n; i++) g.add(new ArrayList<>());
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int from, int to, long cap) {
            g.get(from).add(new Edge(to, g.get(to).size(), cap));
            g.get(to).add(new Edge(from, g.get(from).size() - 1, 0));
        }

        boolean bfs() {
            Arrays.fill(level, -1);
            Queue<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g.get(v)) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long dfs(int v, long f) {
            if (v == t) return f;
            for (int i = it[v]; i < g.get(v).size(); i++) {
                Edge e = g.get(v).get(i);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        g.get(e.to).get(e.rev).cap += d;
                        return d;
                    }
                }
                it[v] = i + 1; // update iterator
            }
            return 0;
        }

        long maxFlow() {
            long flow = 0;
            while (bfs()) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, Long.MAX_VALUE)) > 0) {
                    flow += f;
                }
            }
            return flow;
        }
    }

    static class Pair {
        int x, y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static boolean valid(int x, int y) {
        if (x < 0 || y < 0 || x >= n || y >= n) return false;
        if (sci[x][y] == 'Y' || sci[x][y] == 'Z') return false;
        return true;
    }

    static void bfsZombie(int sx, int sy) {
        for (int i = 0; i < n; i++) Arrays.fill(dis[i], -1);
        Queue<Pair> q = new ArrayDeque<>();
        q.add(new Pair(sx, sy));
        dis[sx][sy] = 0;
        while (!q.isEmpty()) {
            Pair p = q.poll();
            int x = p.x, y = p.y;
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (valid(nx, ny) && dis[nx][ny] == -1) {
                    dis[nx][ny] = dis[x][y] + 1;
                    q.add(new Pair(nx, ny));
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dis[i][j] == -1) dis[i][j] = INF;
            }
        }
    }

    static boolean reachable(int tt, int x0, int y0, int x, int y) {
        if (dis[x0][y0] < tt) return false;
        if (x0 == x && y0 == y) return true;
        if (tt >= t) return false;
        if (dis[x0][y0] <= tt) return false;
        if (dp[tt][x0][y0][x][y] != -1) return dp[tt][x0][y0][x][y] == 1;
        for (int d = 0; d < 4; d++) {
            int nx = x0 + dx[d], ny = y0 + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (sci[nx][ny] == 'Y' || sci[nx][ny] == 'Z') continue;
            if (reachable(tt + 1, nx, ny, x, y)) {
                dp[tt][x0][y0][x][y] = 1;
                return true;
            }
        }
        dp[tt][x0][y0][x][y] = 0;
        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine(); // consume newline
        sci = new char[n][];
        cap = new char[n][];
        for (int i = 0; i < n; i++) {
            sci[i] = sc.nextLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            cap[i] = sc.nextLine().toCharArray();
        }
        dis = new int[n][n];
        // allocate dp: dimensions [t+1][n][n][n][n]
        dp = new int[t+1][n][n][n][n];
        // initialize dp with -1
        for (int a = 0; a <= t; a++) {
            for (int b = 0; b < n; b++) {
                for (int c = 0; c < n; c++) {
                    for (int d = 0; d < n; d++) {
                        Arrays.fill(dp[a][b][c][d], -1);
                    }
                }
            }
        }

        // find zombie
        boolean found = false;
        for (int i = 0; i < n && !found; i++) {
            for (int j = 0; j < n && !found; j++) {
                if (sci[i][j] == 'Z') {
                    bfsZombie(i, j);
                    found = true;
                }
            }
        }

        ArrayList<Pair> scList = new ArrayList<>();
        ArrayList<Pair> cpList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = sci[i][j];
                if (c != 'Z' && c != 'Y' && c != '0') scList.add(new Pair(i, j));
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = cap[i][j];
                if (c != 'Z' && c != 'Y' && c != '0') cpList.add(new Pair(i, j));
            }
        }

        int S = 0;
        int T = scList.size() + cpList.size() + 1;
        Dinic dinic = new Dinic(T + 1, S, T);

        for (int i = 0; i < scList.size(); i++) {
            Pair p = scList.get(i);
            long capacity = sci[p.x][p.y] - '0';
            dinic.addEdge(S, i + 1, capacity);
        }

        for (int j = 0; j < cpList.size(); j++) {
            Pair p = cpList.get(j);
            long capacity = cap[p.x][p.y] - '0';
            dinic.addEdge(scList.size() + 1 + j, T, capacity);
        }

        for (int i = 0; i < scList.size(); i++) {
            Pair sciP = scList.get(i);
            for (int j = 0; j < cpList.size(); j++) {
                Pair capP = cpList.get(j);
                if (reachable(0, sciP.x, sciP.y, capP.x, capP.y)) {
                    dinic.addEdge(i + 1, scList.size() + 1 + j, 10000000L);
                }
            }
        }

        System.out.println(dinic.maxFlow());
    }
}
